package org.kanger;
import java.nio.file.*;
import java.util.*;
import org.kanger.ContextProductionCapture.*;
import org.kanger.ContextProductionNativeBinding.*;

/** Unequal CNF clause shapes retain the whole dual mixed declaration and paired-variable scope. */
public final class ContextDualMixedExistentialScopeRunner {
    static int checks;
    static void require(boolean value,String why){++checks;if(!value)throw new AssertionError(why);}
    static Map<String,Clause> capture(String text,boolean shared,boolean negative,boolean groundHead)throws Exception{
        Result r=ContextAntecedentQuantifierScopeRunner.capture(text);require(r.bound,"dual mixed negative existential binds: "+r.reason);require(r.snapshot.primary.size()==1,"one whole Source");Entry e=r.snapshot.primary.get(0);require(e.kind==Kind.CLAUSES&&e.witnesses()==0&&e.clauses.size()==2,"unequal clauses under one whole Source, no witness");Map<String,Clause> result=new HashMap<>();for(Clause c:e.clauses){boolean solo=c.literals.stream().anyMatch(v->v.predicate.equals("a"));require(c.literals.size()==(solo?2:3)&&c.variables.size()==(solo||shared?1:2),"exact solo/paired literal and variable counts");Atom q=c.literals.stream().filter(v->v.predicate.equals("q")).findFirst().get();require(q.positive!=negative&&q.arguments.size()==(groundHead?1:0)&&(!groundHead||q.arguments.get(0).variable<0),"exact independent consequent sign/arity");for(Atom v:c.literals)if(v!=q)require(v.positive==negative&&v.arguments.size()==1&&v.arguments.get(0).variable>=0,"every complemented input has one universal slot");if(!solo){Atom b=c.literals.stream().filter(v->v.predicate.equals("b")).findFirst().get(),cc=c.literals.stream().filter(v->v.predicate.equals("c")).findFirst().get();require((b.arguments.get(0).variable==cc.arguments.get(0).variable)==shared,"paired b/c slots retain shared or independent binding");}require(result.put(solo?"a":"bc",c)==null,"each route captured once");}require(result.keySet().equals(new HashSet<>(Arrays.asList("a","bc"))),"solo and paired routes both retained");return result;
    }
    static void equivalent(Map<String,Clause> a,Map<String,Clause> b){for(String k:a.keySet())require(a.get(k).equivalent(b.get(k)),"corresponding whole-source route alpha-equivalent: "+k);}
    static void one(boolean negative,boolean groundHead)throws Exception{String s=negative?"~":"",q=s+(groundHead?"q(1)":"q()");Map<String,Clause> shared=capture("!($x ("+s+"a(x)||("+s+"b(x)&&"+s+"c(x))))->"+q+";",true,negative,groundHead),independent=capture("!(($x "+s+"a(x))||(($y "+s+"b(y))&&($z "+s+"c(z))))->"+q+";",false,negative,groundHead);require(shared.get("a").equivalent(independent.get("a")),"solo route independent of other binder scopes");require(!shared.get("bc").equivalent(independent.get("bc")),"paired shared/independent routes differ");equivalent(shared,capture("!@x "+s+"a(x)||("+s+"b(x)&&"+s+"c(x))->"+q+";",true,negative,groundHead));equivalent(independent,capture("!@x @y @z "+s+"a(x)||("+s+"b(y)&&"+s+"c(z))->"+q+";",false,negative,groundHead));equivalent(shared,capture("!($u ("+s+"a(u)||("+s+"b(u)&&"+s+"c(u))))->"+q+";",true,negative,groundHead));equivalent(independent,capture("!(($u "+s+"a(u))||(($v "+s+"b(v))&&($w "+s+"c(w))))->"+q+";",false,negative,groundHead));}
    public static void main(String[] args){try{System.setProperty("user.home",Files.createTempDirectory("dual-mixed-existential-scope-").toString());for(boolean n:new boolean[]{false,true})for(boolean g:new boolean[]{false,true})one(n,g);System.out.println("CONTEXT_DUAL_MIXED_EXISTENTIAL_SCOPE_PASS checks="+(checks+ContextAntecedentQuantifierScopeRunner.checks));System.exit(0);}catch(Throwable e){e.printStackTrace();System.exit(1);}}
}
